-- Import TLC's verified-in-repository authored exercise metadata; YouTube links are reference links, not freshly checked.
-- Existing member-owned content is never changed; curated links and chain metadata are filled only if missing.
ON CONFLICT (slug) DO UPDATE SET youtube_url = COALESCE(public.exercises.youtube_url,EXCLUDED.youtube_url),chain_group=COALESCE(public.exercises.chain_group,EXCLUDED.chain_group),chain_order=COALESCE(public.exercises.chain_order,EXCLUDED.chain_order)
WHERE public.exercises.created_by IS NULL;
